const DEFAULT_CAT_ID = "byte";

function getCatProfile(id) {
  return CAT_PROFILES.find((cat) => cat.id === id) || CAT_PROFILES[0];
}


const clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));

const ACTIONS = Object.freeze({
  IDLE: "idle",
  ROAM: "roam",
  INSPECT: "inspect",
  PLAY: "play",
  JUMP: "jump",
  LOAF: "loaf",
  SLEEP: "sleep",
  GROOM: "groom",
  SEEK_AFFECTION: "seek-affection",
  MISCHIEF: "mischief",
  PURR: "purr",
  HISS: "hiss",
  CLAW: "claw"
});

const DURATIONS = Object.freeze({
  [ACTIONS.IDLE]: [1800, 4200],
  [ACTIONS.ROAM]: [2800, 6500],
  [ACTIONS.INSPECT]: [1800, 4200],
  [ACTIONS.PLAY]: [3200, 6800],
  [ACTIONS.JUMP]: [1300, 2600],
  [ACTIONS.LOAF]: [5000, 11000],
  [ACTIONS.SLEEP]: [9000, 18000],
  [ACTIONS.GROOM]: [3600, 7200],
  [ACTIONS.SEEK_AFFECTION]: [2600, 5200],
  [ACTIONS.MISCHIEF]: [2400, 5600],
  [ACTIONS.PURR]: [1600, 3200],
  [ACTIONS.HISS]: [1100, 2100],
  [ACTIONS.CLAW]: [700, 1400]
});

const DEFAULT_DRIVES = Object.freeze({
  energy: 0.76,
  curiosity: 0.62,
  affection: 0.58,
  playfulness: 0.56,
  confidence: 0.72,
  anger: 0.08
});

const DEFAULT_INSTINCTS = Object.freeze({
  sleep: 1,
  play: 1,
  roam: 1,
  jump: 1,
  mischief: 1,
  affection: 1,
  temper: 0.55,
  petIrritation: -0.025,
  calmRate: 1,
  hissThreshold: 0.66,
  clawThreshold: 0.86
});

class CatBrain {
  constructor({ random = Math.random, profile = null } = {}) {
    this.random = random;
    this.profileId = profile?.id || "byte";
    this.favoriteToys = [...(profile?.favoriteToys || [])];
    this.drives = { ...DEFAULT_DRIVES, ...profile?.drives };
    this.instincts = { ...DEFAULT_INSTINCTS, ...profile?.instincts };
    this.currentAction = ACTIONS.IDLE;
    this.actionUntil = 0;
    this.memory = {
      petCount: 0,
      jumpsLanded: 0,
      favoritePlatformId: "floor",
      platformVisits: { floor: 1 },
      lastPetAt: 0,
      lastToyAt: 0
    };
  }

  tick(dt, context = {}) {
    const seconds = clamp(dt, 0, 0.25);
    const sleeping = this.currentAction === ACTIONS.SLEEP;
    const loafing = this.currentAction === ACTIONS.LOAF;

    if (sleeping) {
      this.drives.energy += 0.034 * seconds;
      this.drives.curiosity += 0.004 * seconds;
      this.drives.playfulness += 0.006 * seconds;
      this.drives.anger -= 0.026 * this.instincts.calmRate * seconds;
    } else {
      this.drives.energy -= (loafing ? 0.001 : 0.0038) * seconds;
      this.drives.curiosity += (context.pointerMoved ? 0.012 : 0.006) * seconds;
      this.drives.playfulness += (context.toyAvailable ? 0.012 : 0.004) * seconds;
      this.drives.affection -= 0.0014 * seconds;
      this.drives.anger -= 0.009 * this.instincts.calmRate * seconds;
    }

    if (context.pointerNear) this.drives.confidence += 0.003 * seconds;
    if (context.loudMotion) {
      this.drives.confidence -= 0.008 * seconds;
      this.drives.anger += 0.052 * this.instincts.temper * seconds;
    }
    if (this.currentAction === ACTIONS.HISS || this.currentAction === ACTIONS.CLAW) {
      this.drives.anger -= 0.018 * seconds;
    }

    for (const key of Object.keys(this.drives)) {
      this.drives[key] = clamp(this.drives[key]);
    }
  }

  pet(strength = 1, now = Date.now()) {
    const amount = clamp(strength, 0.1, 2);
    const repeatPet = now - this.memory.lastPetAt < 650;
    this.drives.affection = clamp(this.drives.affection + 0.055 * amount * this.instincts.affection);
    this.drives.confidence = clamp(this.drives.confidence + 0.018 * amount);
    this.drives.playfulness = clamp(this.drives.playfulness + 0.012 * amount);
    this.drives.anger = clamp(
      this.drives.anger + this.instincts.petIrritation * amount + (repeatPet ? 0.055 * this.instincts.temper : 0)
    );
    this.memory.petCount += 1;
    this.memory.lastPetAt = now;
    if (this.drives.anger >= this.instincts.clawThreshold && repeatPet) {
      this.setAction(ACTIONS.CLAW, now, 900 + amount * 180);
    } else if (this.drives.anger >= this.instincts.hissThreshold) {
      this.setAction(ACTIONS.HISS, now, 1250 + amount * 220);
    } else {
      this.setAction(ACTIONS.PURR, now, 1500 + amount * 450);
    }
    return this.currentAction;
  }

  noticeToy(now = Date.now()) {
    this.drives.playfulness = clamp(this.drives.playfulness + 0.16);
    this.drives.curiosity = clamp(this.drives.curiosity + 0.12);
    this.memory.lastToyAt = now;
    this.actionUntil = 0;
  }

  rememberLanding(platformId) {
    if (!platformId) return;
    this.memory.jumpsLanded += 1;
    this.memory.platformVisits[platformId] = (this.memory.platformVisits[platformId] || 0) + 1;
    const currentFavorite = this.memory.platformVisits[this.memory.favoritePlatformId] || 0;
    if (this.memory.platformVisits[platformId] > currentFavorite) {
      this.memory.favoritePlatformId = platformId;
    }
  }

  scoreActions(context = {}) {
    const d = this.drives;
    const quiet = context.quiet ? 1 : 0;
    const pointerNear = context.pointerNear ? 1 : 0;
    const toy = context.toyAvailable ? 1 : 0;
    const favoriteToy = context.toyType && this.favoriteToys.includes(context.toyType) ? 1 : 0;
    const highPlatform = context.onHighPlatform ? 1 : 0;
    const reachable = Math.min(1, (context.reachablePlatforms || 0) / 3);

    const scores = {
      [ACTIONS.IDLE]: 0.36 + d.confidence * 0.26 + (1 - d.curiosity) * 0.18,
      [ACTIONS.ROAM]: d.curiosity * 1.08 + d.energy * 0.34,
      [ACTIONS.INSPECT]: d.curiosity * 0.78 + pointerNear * 0.42,
      [ACTIONS.PLAY]: d.playfulness * 1.18 + toy * 0.78 + favoriteToy * 0.44 + d.energy * 0.22,
      [ACTIONS.JUMP]: d.curiosity * 0.62 + d.playfulness * 0.36 + reachable * 0.48,
      [ACTIONS.LOAF]: (1 - d.energy) * 0.82 + d.confidence * 0.5 + quiet * 0.18,
      [ACTIONS.SLEEP]: (1 - d.energy) * 1.82 + quiet * 0.48 + highPlatform * 0.14,
      [ACTIONS.GROOM]: d.confidence * 0.54 + (1 - d.curiosity) * 0.26 + quiet * 0.1,
      [ACTIONS.SEEK_AFFECTION]: (1 - d.affection) * 1.08 + pointerNear * 0.38,
      [ACTIONS.MISCHIEF]: d.playfulness * 0.72 + d.curiosity * 0.52 + d.confidence * 0.16,
      [ACTIONS.HISS]: d.anger * 1.48 + pointerNear * 0.24 + this.instincts.temper * 0.08,
      [ACTIONS.CLAW]: d.anger * 1.68 + pointerNear * 0.46 + this.instincts.temper * 0.12
    };

    scores[ACTIONS.SLEEP] *= this.instincts.sleep;
    scores[ACTIONS.PLAY] *= this.instincts.play;
    scores[ACTIONS.ROAM] *= this.instincts.roam;
    scores[ACTIONS.JUMP] *= this.instincts.jump;
    scores[ACTIONS.MISCHIEF] *= this.instincts.mischief;
    scores[ACTIONS.SEEK_AFFECTION] *= this.instincts.affection;

    if (!context.pointerVisible) {
      scores[ACTIONS.INSPECT] *= 0.4;
      scores[ACTIONS.SEEK_AFFECTION] *= 0.55;
    }
    if (!context.toyAvailable) scores[ACTIONS.PLAY] *= 0.62;
    if (!context.canJump) scores[ACTIONS.JUMP] = -1;
    if (d.anger < this.instincts.hissThreshold) scores[ACTIONS.HISS] = -1;
    if (!context.pointerNear || d.anger < this.instincts.clawThreshold) scores[ACTIONS.CLAW] = -1;
    if (d.energy < 0.2) scores[ACTIONS.SLEEP] += 1.2;
    if (d.energy < 0.12) scores[ACTIONS.ROAM] *= 0.25;

    for (const action of Object.keys(scores)) {
      scores[action] += this.random() * 0.16;
    }
    return scores;
  }

  decide(context = {}, now = Date.now()) {
    if (now < this.actionUntil && this.currentAction !== ACTIONS.IDLE) {
      return this.currentAction;
    }

    const scores = this.scoreActions(context);
    const [action] = Object.entries(scores).sort((a, b) => b[1] - a[1])[0];
    this.setAction(action, now);

    if (action === ACTIONS.PLAY) {
      this.drives.playfulness = clamp(this.drives.playfulness - 0.2);
    } else if (action === ACTIONS.ROAM || action === ACTIONS.JUMP) {
      this.drives.curiosity = clamp(this.drives.curiosity - 0.12);
    } else if (action === ACTIONS.SEEK_AFFECTION) {
      this.drives.affection = clamp(this.drives.affection + 0.025);
    } else if (action === ACTIONS.HISS) {
      this.drives.anger = clamp(this.drives.anger - 0.08);
    } else if (action === ACTIONS.CLAW) {
      this.drives.anger = clamp(this.drives.anger - 0.14);
    }
    return action;
  }

  setAction(action, now = Date.now(), durationOverride = null) {
    this.currentAction = action;
    const [min, max] = DURATIONS[action] || DURATIONS[ACTIONS.IDLE];
    const duration = durationOverride ?? min + this.random() * (max - min);
    this.actionUntil = now + duration;
  }

  snapshot() {
    return {
      action: this.currentAction,
      actionUntil: this.actionUntil,
      drives: { ...this.drives },
      memory: {
        ...this.memory,
        platformVisits: { ...this.memory.platformVisits }
      }
    };
  }
}


const CAT_MAX_RISE = 320;

function horizontalGap(a, b) {
  if (a.right < b.left) return b.left - a.right;
  if (b.right < a.left) return a.left - b.right;
  return 0;
}

function canTraverse(from, to, jumpReach = 1) {
  if (!from || !to || from.id === to.id) return false;
  const rise = from.top - to.top;
  const gap = horizontalGap(from, to);
  if (rise > 0) return rise <= CAT_MAX_RISE * Math.max(1, jumpReach) && gap < 370;
  const hasDropExit = gap > 0 || to.left < from.left - 30 || to.right > from.right + 30;
  return gap < 440 && hasDropExit;
}

function reachablePlatforms(platforms, from, x, jumpReach = 1) {
  if (!from) return [];
  return platforms.filter((candidate) => {
    if (!canTraverse(from, candidate, jumpReach)) return false;
    const safeLeft = candidate.left + Math.min(42, candidate.width * 0.25);
    const safeRight = candidate.right - Math.min(42, candidate.width * 0.25);
    const nearestLanding = Math.min(safeRight, Math.max(safeLeft, x));
    return Math.abs(nearestLanding - x) < 470;
  });
}

function nextHopToward(platforms, from, destination, jumpReach = 1) {
  if (!from || !destination || from.id === destination.id) return null;
  const queue = [{ platform: from, firstHop: null }];
  const visited = new Set([from.id]);
  const descending = destination.top > from.top;
  const routeScore = (platform) => {
    const overshootsDownwardTarget = descending && platform.top > destination.top;
    return Math.abs(platform.top - destination.top) + (overshootsDownwardTarget ? 10_000 : 0);
  };
  const orderedPlatforms = [...platforms].sort((a, b) => routeScore(a) - routeScore(b));

  while (queue.length) {
    const current = queue.shift();
    for (const candidate of orderedPlatforms) {
      if (visited.has(candidate.id) || !canTraverse(current.platform, candidate, jumpReach)) continue;
      const firstHop = current.firstHop || candidate;
      if (candidate.id === destination.id) return firstHop;
      visited.add(candidate.id);
      queue.push({ platform: candidate, firstHop });
    }
  }
  return null;
}

function platformForTarget(platforms, x, y, snapDistance = 150) {
  return platforms
    .filter((platform) => x >= platform.left && x <= platform.right)
    .map((platform) => {
      const bottom = Number.isFinite(platform.bottom) ? platform.bottom : platform.top;
      const inside = y >= platform.top && y <= bottom;
      const verticalDistance = inside ? 0 : Math.abs(platform.top - y);
      return { platform, inside, verticalDistance };
    })
    .filter(({ inside, verticalDistance }) => inside || verticalDistance <= snapDistance)
    .sort((a, b) => {
      if (a.inside !== b.inside) return a.inside ? -1 : 1;
      if (a.verticalDistance !== b.verticalDistance) return a.verticalDistance - b.verticalDistance;
      return a.platform.width - b.platform.width;
    })[0]?.platform || null;
}

function launchPoint(from, to) {
  const inset = Math.min(44, from.width * 0.25);
  if (to.right < from.left) return from.left + inset;
  if (to.left > from.right) return from.right - inset;
  const targetCenter = (to.left + to.right) / 2;
  return Math.min(from.right - inset, Math.max(from.left + inset, targetCenter));
}

function clampNavigation(value, minimum, maximum) {
  return Math.min(maximum, Math.max(minimum, value));
}

function chooseTetherAnchor(platforms, start, destination, viewportWidth) {
  const midpointX = (start.x + destination.x) / 2;
  const highestCatPoint = Math.min(start.y, destination.y);
  const ceilingY = highestCatPoint - 54;
  const candidates = platforms
    .filter((platform) => platform.id !== "floor" && platform.top + 18 < ceilingY)
    .map((platform) => {
      const x = clampNavigation(midpointX, platform.left + 18, platform.right - 18);
      const y = Math.min(platform.bottom - 12, platform.top + 18);
      const horizontalDistance = Math.abs(x - midpointX);
      const verticalDistance = Math.abs(y - (ceilingY - 82));
      return { x, y, platformId: platform.id, score: horizontalDistance + verticalDistance * 0.28 };
    })
    .sort((a, b) => a.score - b.score);
  if (candidates.length) {
    const { x, y, platformId } = candidates[0];
    return { x, y, platformId };
  }
  return {
    x: clampNavigation(midpointX, 42, Math.max(42, viewportWidth - 42)),
    y: 18,
    platformId: "page-top"
  };
}

function sampleSwingArc(swing, now) {
  const progress = clampNavigation((now - swing.startedAt) / swing.duration, 0, 1);
  const eased = (1 - Math.cos(Math.PI * progress)) / 2;
  const startDx = swing.startX - swing.anchorX;
  const startDy = swing.startY - swing.anchorY;
  const endDx = swing.endX - swing.anchorX;
  const endDy = swing.endY - swing.anchorY;
  const startAngle = Math.atan2(startDy, startDx);
  const endAngle = Math.atan2(endDy, endDx);
  let angleDelta = endAngle - startAngle;
  while (angleDelta > Math.PI) angleDelta -= Math.PI * 2;
  while (angleDelta < -Math.PI) angleDelta += Math.PI * 2;
  const startRadius = Math.hypot(startDx, startDy);
  const endRadius = Math.hypot(endDx, endDy);
  const ropeStretch = Math.sin(Math.PI * progress) * Math.min(48, Math.abs(swing.endX - swing.startX) * 0.11);
  const radius = startRadius + (endRadius - startRadius) * eased + ropeStretch;
  const angle = startAngle + angleDelta * eased;
  return {
    x: swing.anchorX + Math.cos(angle) * radius,
    y: swing.anchorY + Math.sin(angle) * radius,
    progress,
    complete: progress >= 1
  };
}


const TARGET_FRAME_MS = 1000 / 60;

const blend = (current, sample, weight) => current + (sample - current) * weight;

class PerformanceGovernor {
  constructor({ enterPressure = 28, recoveryFrames = 300 } = {}) {
    this.mode = "full";
    this.frameMs = TARGET_FRAME_MS;
    this.workMs = 0;
    this.pressure = 0;
    this.recovery = 0;
    this.enterPressure = enterPressure;
    this.recoveryFrames = recoveryFrames;
  }

  sample(frameMs, workMs) {
    if (!(frameMs > 0) || frameMs > 120 || !(workMs >= 0)) return null;
    this.frameMs = blend(this.frameMs, frameMs, 0.06);
    this.workMs = blend(this.workMs, workMs, 0.08);
    const underPressure = this.frameMs > 21.5 || this.workMs > 7.5;

    if (underPressure) {
      this.pressure = Math.min(this.enterPressure, this.pressure + 1);
      this.recovery = 0;
    } else {
      this.pressure = Math.max(0, this.pressure - 0.5);
      if (this.mode === "lite" && this.frameMs < 18.5 && this.workMs < 5) this.recovery += 1;
    }

    if (this.mode === "full" && this.pressure >= this.enterPressure) {
      this.mode = "lite";
      this.pressure = 0;
      return this.mode;
    }
    if (this.mode === "lite" && this.recovery >= this.recoveryFrames) {
      this.mode = "full";
      this.recovery = 0;
      return this.mode;
    }
    return null;
  }

  snapshot() {
    return {
      mode: this.mode,
      frameMs: this.frameMs,
      workMs: this.workMs,
      fps: Math.min(60, Math.round(1000 / Math.max(TARGET_FRAME_MS, this.frameMs)))
    };
  }
}


const TOY_RADIUS = 10;
const TOY_GRAVITY = 1180;

const clampToyValue = (value, min, max) => Math.min(max, Math.max(min, value));

function createToy({ x, y, vx = 0, vy = 0, platformId = null, now = 0 }) {
  return {
    x,
    y,
    vx,
    vy,
    radius: TOY_RADIUS,
    platformId,
    grounded: false,
    spawnedAt: now,
    lastKickedAt: -Infinity,
    bounceCount: 0,
    hitCount: 0
  };
}

function advanceToy(toy, dt, width) {
  const seconds = clampToyValue(dt, 0, 0.04);
  const previousBottom = toy.y + toy.radius;

  if (toy.grounded) {
    toy.vy = 0;
    toy.vx *= Math.pow(0.965, seconds * 60);
    if (Math.abs(toy.vx) < 3) toy.vx = 0;
  } else {
    toy.vy += TOY_GRAVITY * seconds;
  }

  toy.x += toy.vx * seconds;
  toy.y += toy.vy * seconds;

  if (toy.x - toy.radius < 0) {
    toy.x = toy.radius;
    toy.vx = Math.abs(toy.vx) * 0.76;
  } else if (toy.x + toy.radius > width) {
    toy.x = width - toy.radius;
    toy.vx = -Math.abs(toy.vx) * 0.76;
  }

  return previousBottom;
}

function bounceToy(toy, surfaceTop, platformId) {
  const impactSpeed = Math.abs(toy.vy);
  toy.y = surfaceTop - toy.radius - 0.5;
  toy.platformId = platformId;
  toy.bounceCount += 1;
  toy.vx *= 0.91;

  if (impactSpeed < 72) {
    toy.vy = 0;
    toy.grounded = true;
  } else {
    toy.vy = -impactSpeed * 0.57;
    toy.grounded = false;
  }
  return impactSpeed;
}

function kickToy(toy, direction, strength = 1, now = 0) {
  const force = clampToyValue(strength, 0.65, 1.35);
  const side = Math.sign(direction) || 1;
  toy.vx = side * (210 + 80 * force);
  toy.vy = -(235 + 115 * force);
  toy.grounded = false;
  toy.lastKickedAt = now;
  toy.hitCount += 1;
}

function isToyOnSurface(toy, platform) {
  if (!platform) return false;
  const overlaps = toy.x + toy.radius > platform.left + 1 && toy.x - toy.radius < platform.right - 1;
  const closeToTop = Math.abs(toy.y + toy.radius - platform.top) < 4;
  return overlaps && closeToTop;
}


const clampInteraction = (value, min, max) => Math.min(max, Math.max(min, value));

const BOX_WIDTH = 92;
const BOX_HEIGHT = 56;
const BOX_GRAVITY = 980;
const FISHING_LINE_LENGTH = 104;
const FISHING_REELED_LENGTH = 34;
const MOUSE_WIDTH = 42;
const MOUSE_HEIGHT = 24;
const MOUSE_GRAVITY = 980;

function createBox({ x, y, vx = 0, vy = 0, platformId = null }) {
  return {
    x,
    y,
    vx,
    vy,
    width: BOX_WIDTH,
    height: BOX_HEIGHT,
    platformId,
    grounded: Boolean(platformId)
  };
}

function advanceBox(box, dt, width) {
  const seconds = clampInteraction(dt, 0, 0.04);
  const previousBottom = box.y + box.height;

  if (box.grounded) {
    box.vy = 0;
    box.vx *= Math.pow(0.9, seconds * 60);
    if (Math.abs(box.vx) < 2) box.vx = 0;
  } else {
    box.vy += BOX_GRAVITY * seconds;
  }

  box.x += box.vx * seconds;
  box.y += box.vy * seconds;

  if (box.x < 0) {
    box.x = 0;
    box.vx = Math.abs(box.vx) * 0.24;
  } else if (box.x + box.width > width) {
    box.x = width - box.width;
    box.vx = -Math.abs(box.vx) * 0.24;
  }

  return previousBottom;
}

function settleBox(box, surfaceTop, platformId) {
  box.y = surfaceTop - box.height;
  box.vy = 0;
  box.vx *= 0.35;
  box.grounded = true;
  box.platformId = platformId;
}

function isBoxOnSurface(box, platform) {
  if (!platform) return false;
  const overlaps = box.x + box.width - 8 > platform.left && box.x + 8 < platform.right;
  const flush = Math.abs(box.y + box.height - platform.top) < 4;
  return overlaps && flush;
}

function createFishingRig({ x, y, direction = 1 }) {
  const facing = direction < 0 ? -1 : 1;
  const tipX = x + facing * 68;
  const tipY = y - 42;
  return {
    targetX: x,
    targetY: y,
    handleX: x,
    handleY: y,
    tipX,
    tipY,
    lureX: tipX,
    lureY: tipY + FISHING_LINE_LENGTH,
    lureVx: 0,
    lureVy: 0,
    handleVx: 0,
    handleVy: 0,
    direction: facing,
    lineLength: FISHING_LINE_LENGTH,
    reeling: false,
    castBoost: 0,
    lastHitAt: -Infinity,
    hitCount: 0
  };
}

function setFishingHandle(rig, x, y) {
  rig.targetX = x;
  rig.targetY = y;
}

function setFishingReel(rig, reeling) {
  if (!rig) return;
  const wasReeling = rig.reeling;
  rig.reeling = Boolean(reeling);
  if (wasReeling && !rig.reeling) {
    rig.castBoost = Math.min(1, Math.hypot(rig.handleVx, rig.handleVy) / 1100 + 0.24);
    rig.lureVx += rig.direction * (110 + rig.castBoost * 250) + rig.handleVx * 0.12;
    rig.lureVy += -80 - rig.castBoost * 190 + rig.handleVy * 0.08;
  }
}

function advanceFishingRig(rig, dt, width, height) {
  const seconds = clampInteraction(dt, 1 / 240, 0.035);
  const previousHandleX = rig.handleX;
  const previousHandleY = rig.handleY;

  // The handle is locked to the latest pointer sample. Only the lure trails.
  rig.handleX = rig.targetX;
  rig.handleY = rig.targetY;
  const rawHandleVx = (rig.handleX - previousHandleX) / seconds;
  const rawHandleVy = (rig.handleY - previousHandleY) / seconds;
  rig.handleVx = clampInteraction(rig.handleVx * 0.18 + rawHandleVx * 0.82, -2400, 2400);
  rig.handleVy = clampInteraction(rig.handleVy * 0.18 + rawHandleVy * 0.82, -2400, 2400);

  // A small dead zone stops the rod from flickering when the cursor crosses center.
  const center = width / 2;
  if (rig.handleX < center - 18) rig.direction = 1;
  else if (rig.handleX > center + 18) rig.direction = -1;

  rig.tipX = clampInteraction(rig.handleX + rig.direction * 76 + rig.handleVx * 0.0045, 8, width - 8);
  rig.tipY = clampInteraction(rig.handleY - 46 + rig.handleVy * 0.003, 8, height - 8);

  const targetLength = rig.reeling ? FISHING_REELED_LENGTH : FISHING_LINE_LENGTH;
  const reelEase = 1 - Math.exp(-(rig.reeling ? 15 : 8) * seconds);
  rig.lineLength += (targetLength - rig.lineLength) * reelEase;

  // Two tiny spring steps are more stable during a violent whip while remaining cheap.
  const steps = seconds > 0.018 ? 2 : 1;
  const step = seconds / steps;
  for (let index = 0; index < steps; index += 1) {
    const speedLift = Math.min(24, Math.hypot(rig.handleVx, rig.handleVy) * 0.012);
    const restingX = rig.tipX - rig.handleVx * 0.018;
    const restingY = rig.tipY + rig.lineLength - speedLift;
    const stiffness = rig.reeling ? 176 : 104;
    rig.lureVx += (restingX - rig.lureX) * stiffness * step;
    rig.lureVy += ((restingY - rig.lureY) * stiffness + 74) * step;
    const damping = Math.exp(-(rig.reeling ? 10.8 : 6.6) * step);
    rig.lureVx = clampInteraction(rig.lureVx * damping, -1750, 1750);
    rig.lureVy = clampInteraction(rig.lureVy * damping, -1750, 1750);
    rig.lureX += rig.lureVx * step;
    rig.lureY += rig.lureVy * step;
  }
  rig.castBoost = Math.max(0, rig.castBoost - seconds * 1.8);

  const postDx = rig.lureX - rig.tipX;
  const postDy = rig.lureY - rig.tipY;
  const postDistance = Math.max(0.001, Math.hypot(postDx, postDy));
  const maximumLength = rig.lineLength * 1.16;
  if (postDistance > maximumLength) {
    rig.lureX = rig.tipX + postDx / postDistance * maximumLength;
    rig.lureY = rig.tipY + postDy / postDistance * maximumLength;
    rig.lureVx *= 0.72;
    rig.lureVy *= 0.72;
  }

  if (rig.lureX < 12 || rig.lureX > width - 12) {
    rig.lureX = clampInteraction(rig.lureX, 12, width - 12);
    rig.lureVx *= -0.35;
  }
  if (rig.lureY < 12 || rig.lureY > height - 44) {
    rig.lureY = clampInteraction(rig.lureY, 12, height - 44);
    rig.lureVy *= -0.3;
  }

  return rig;
}

function strikeFishingLure(rig, direction, force = 1, now = 0) {
  if (!rig || now - rig.lastHitAt < 520) return false;
  const side = Math.sign(direction) || 1;
  const strength = clampInteraction(force, 0.65, 1.5);
  rig.lureVx = side * (240 + 150 * strength);
  rig.lureVy = -(210 + 90 * strength);
  rig.lastHitAt = now;
  rig.hitCount += 1;
  rig.castBoost = 1;
  return true;
}

function createMouse({ x, y, vx = 0, vy = 0, platformId = null, now = 0, direction = 1 }) {
  return {
    x,
    y,
    vx,
    vy,
    width: MOUSE_WIDTH,
    height: MOUSE_HEIGHT,
    direction: direction < 0 ? -1 : 1,
    platformId,
    grounded: Boolean(platformId),
    spawnedAt: now,
    dashUntil: now + 900,
    nextTurnAt: now + 1700,
    lastPouncedAt: -Infinity,
    pounceCount: 0
  };
}

function advanceMouse(mouse, dt, width, now = 0, platform = null) {
  const seconds = clampInteraction(dt, 0, 0.04);
  const previousBottom = mouse.y + mouse.height;

  if (mouse.grounded) {
    const fast = now < mouse.dashUntil;
    const targetSpeed = mouse.direction * (fast ? 188 : 82);
    mouse.vx += (targetSpeed - mouse.vx) * (1 - Math.exp(-10 * seconds));
    mouse.vy = 0;

    if (platform) {
      const left = platform.left + 5;
      const right = platform.right - mouse.width - 5;
      if (mouse.x <= left && mouse.direction < 0) {
        mouse.x = left;
        mouse.direction = 1;
        mouse.dashUntil = now + 520;
      } else if (mouse.x >= right && mouse.direction > 0) {
        mouse.x = right;
        mouse.direction = -1;
        mouse.dashUntil = now + 520;
      }
    }

    if (now >= mouse.nextTurnAt) {
      mouse.direction *= -1;
      mouse.dashUntil = now + 620;
      mouse.nextTurnAt = now + 1700;
    }
  } else {
    mouse.vy += MOUSE_GRAVITY * seconds;
  }

  mouse.x += mouse.vx * seconds;
  mouse.y += mouse.vy * seconds;

  if (mouse.x < 0) {
    mouse.x = 0;
    mouse.direction = 1;
    mouse.vx = Math.abs(mouse.vx) * 0.32;
  } else if (mouse.x + mouse.width > width) {
    mouse.x = width - mouse.width;
    mouse.direction = -1;
    mouse.vx = -Math.abs(mouse.vx) * 0.32;
  }

  return previousBottom;
}

function settleMouse(mouse, surfaceTop, platformId) {
  mouse.y = surfaceTop - mouse.height;
  mouse.vy = 0;
  mouse.grounded = true;
  mouse.platformId = platformId;
}

function isMouseOnSurface(mouse, platform) {
  if (!platform) return false;
  const overlaps = mouse.x + mouse.width - 5 > platform.left && mouse.x + 5 < platform.right;
  const flush = Math.abs(mouse.y + mouse.height - platform.top) < 4;
  return overlaps && flush;
}

function pounceMouse(mouse, catDirection, force = 1, now = 0) {
  if (!mouse || now - mouse.lastPouncedAt < 640) return false;
  const side = Math.sign(catDirection) || 1;
  const strength = clampInteraction(force, 0.65, 1.5);
  mouse.direction = side;
  mouse.vx = side * (205 + strength * 90);
  mouse.vy = -(70 + strength * 42);
  mouse.grounded = false;
  mouse.platformId = null;
  mouse.dashUntil = now + 1150;
  mouse.nextTurnAt = now + 2100;
  mouse.lastPouncedAt = now;
  mouse.pounceCount += 1;
  return true;
}

function createBubble({ x, y, now = 0, seed = 0 }) {
  return {
    x,
    y,
    radius: 9 + seed % 5,
    vx: -12 + seed % 25,
    vy: -34 - seed % 22,
    bornAt: now,
    phase: seed * 0.73,
    popped: false
  };
}

function advanceBubble(bubble, dt, width, height, now = 0) {
  const seconds = clampInteraction(dt, 0, 0.04);
  bubble.phase += seconds * 2.8;
  bubble.vx += Math.sin(bubble.phase) * 5.5 * seconds;
  bubble.vx = clampInteraction(bubble.vx, -32, 32);
  bubble.x += bubble.vx * seconds;
  bubble.y += bubble.vy * seconds;
  bubble.x = clampInteraction(bubble.x, bubble.radius + 4, width - bubble.radius - 4);
  return !bubble.popped && bubble.y + bubble.radius > 4 && bubble.y < height + bubble.radius && now - bubble.bornAt < 7200;
}

function segmentGeometry(fromX, fromY, toX, toY) {
  const dx = toX - fromX;
  const dy = toY - fromY;
  return {
    x: fromX,
    y: fromY,
    length: Math.hypot(dx, dy),
    angle: Math.atan2(dy, dx) * 180 / Math.PI
  };
}


