    this.brain = new CatBrain({ profile: this.profile });
    this.x = Math.max(60, window.innerWidth * 0.56);
    this.y = window.innerHeight - 38 - CAT_SIZE + CAT_FOOT_OFFSET;
    this.vx = 0;
    this.vy = 0;
    this.facing = -1;
    this.grounded = true;
    this.platformId = "floor";
