  event.preventDefault();
  event.stopPropagation();
  if (cat.startDrag("bubble-machine", event)) {
    try { bubbleMachineElement.setPointerCapture?.(event.pointerId); } catch { /* Synthetic test events have no native capture target. */ }
  }
